import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

export default function Loginpage(props) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [loginStatus, setLoginStatus] = useState(false);
  const [data, setData] = useState([]);
  const navigate = useNavigate();
  let matchedUser = null;

  function handleUsernameChange(event) {
    setUsername(event.target.value);
  }

  function handlePasswordChange(event) {
    setPassword(event.target.value);
  }

  useEffect(() => {
    fetch("http://localhost:3000/data").then((response) =>
      response.json().then((user) => setData(user))
    );
  }, []);

  const handleSubmit = (event) => {
    event.preventDefault();
    const isValidUser = data.some((user) => {
      if (user.username === username && user.password === password) {
        matchedUser = user;
        return true;
      }
      return false;
    });

    if (isValidUser) {
      setLoginStatus(true);
      alert("Login successful!");
      props.auth(true);
      props.user = matchedUser.username;
      return navigate("/profile");
    } else {
      setLoginStatus(false);
      alert("Invalid login. Please try again.");
      props.auth(false);
      return navigate("/login");
    }
    //setUsername("");
    //setPassword("");
  };

  return (
    <div className="container">
      <h2> Login Page: </h2>
      <form onSubmit={handleSubmit} className="form">
        <label htmlFor="username" className="pa label">
          Username:
        </label>
        <input
          className="pa input"
          type="text"
          id="username"
          placeholder="Username"
          required
          onChange={handleUsernameChange}
        />
        <label htmlFor="password" className="pa label">
          Password:
        </label>
        <input
          className="pa input"
          type="password"
          id="password"
          placeholder="Password"
          required
          onChange={handlePasswordChange}
        />
        <button className="pa  btn" type="submit">
          Log in
        </button>
        <button
          className="pa reg-btn"
          onClick={() => props.onFormSwitch("register")}
        >
          Don't have an account Register here
        </button>
      </form>
    </div>
  );
}
